package com.example.starter.domain;

/**
 * 批次流转状态。
 */
public enum LotStatus {

    /** 已申报，田间检验与室内检测尚未齐回。 */
    DECLARED,
    /** 待定：一项不合格而另一项尚未回，或结论尚未形成。 */
    PENDING,
    /** 首检不合格，可在窗口内申请复检。 */
    UNQUALIFIED,
    /** 复检已受理，复检（第二轮）检验尚未齐回。 */
    RECHECKING,
    /** 分级合格，待发证。 */
    QUALIFIED,
    /** 已发证。 */
    CERTIFIED,
    /** 已注销（终态）。 */
    CANCELLED
}

package com.example.starter.domain;

/**
 * 种子等级（分级结论与证书等级）。
 */
public enum Grade {

    /** 原种：田间纯度 ≥ 99.9%，室内发芽率 ≥ 90%。 */
    ORIGINAL,
    /** 良种：田间纯度 ≥ 99.0%，室内发芽率 ≥ 85%。 */
    BREEDER
}

package com.example.starter.domain;

/**
 * 证书状态。
 */
public enum CertStatus {

    /** 有效。 */
    VALID,
    /** 已作废（批次注销时同步作废并留痕）。 */
    VOID
}

package com.example.starter.domain;

/**
 * 幂等请求类型，参与 requestId 指纹计算。
 */
public enum RequestType {

    /** 批次申报。 */
    DECLARE,
    /** 田间检验提交。 */
    FIELD,
    /** 室内检测提交。 */
    LAB,
    /** 复检申请受理。 */
    RECHECK,
    /** 发证。 */
    ISSUE,
    /** 注销。 */
    CANCEL
}

