package com.example.starter.domain;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 复检申请行（每批次至多一条）。
 *
 * @param id         主键
 * @param lotId      批次主键
 * @param requestId  复检受理幂等键
 * @param status     申请状态
 * @param appliedAt  申请提交时间（UTC）
 * @param deadlineAt 受理截止日（UTC 日界，含当日）
 * @param createdAt  入库时间（UTC）
 */
public record RecheckApplication(
        Long id,
        long lotId,
        String requestId,
        String status,
        Instant appliedAt,
        LocalDate deadlineAt,
        Instant createdAt) {
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 幂等请求记录行。
 *
 * @param requestId   幂等键
 * @param requestType 请求类型
 * @param fingerprint  requestId 与全部业务字段的 SHA-256 指纹
 * @param lotId       关联批次；申报前为空
 * @param resultRef   首次成功结果引用
 * @param createdAt   入库时间（UTC）
 */
public record IdempotentRequest(
        String requestId,
        RequestType requestType,
        String fingerprint,
        Long lotId,
        String resultRef,
        Instant createdAt) {
}

