    public MutableClock(Instant fixed, ZoneId zone) {
        this.fixed = fixed;
        this.zone = zone;
    }

    public void setInstant(Instant instant) {
        this.fixed = instant;
    }

    @Override
    public ZoneId getZone() {
        return zone;
    }

    @Override
    public Clock withZone(ZoneId zone) {
        return new MutableClock(fixed, zone);
    }

    @Override
    public Instant instant() {
        return fixed;
    }
}

