        assertEquals("CANCELLED", finalLot.status(), "注销最终必须生效（终态）");
        if (finalLot.certificate() != null) {
            // 发证若在注销前成功，其证书必须已被注销事务同步作废。
            assertEquals("VOID", finalLot.certificate().status());
