        throw new ConflictException("requestId 已用于不同业务参数的请求: " + requestId);
    }
    if (latest.resultSnapshot() == null) {
        throw new ConflictException("相同 requestId 的首次请求仍在处理中: " + requestId);
    }
    return latest;
}

